INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=19760&keyref=6007623', '3A1362', now(), 'Official SAM source captured 2026-09-11. Whole-property sale THB 7,935,000; 220 sq.wah; two-storey building surveyed as 20 rental rooms. Registered acquisitions residential building and garage. Private road deed 138455 with SAM-reported registered pedestrian/vehicle/utilities easement. No rent roll, income, tenancy or yields inferred. 20 source images retained, building photos dated 2023-10-08. Coordinates extracted from navigation and cross-checked with map. All-status duplicate search found no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: 20-Room Apartment Building, Huai Kapi 16, THB 7.935M', 'Two-storey rental-room building with 20 rooms according to the SAM survey, without a stated house number, in Soi Huai Kapi 16, Huai Kapi, Mueang Chon Buri, Chon Buri. Deed 138457 covers 220 sq.wah (880 sq.m.). SAM announced price THB 7,935,000; asset 3A1362. This is a sale of the whole property, not an individual room rental offer.
